import { tags } from "typia";

import { IShoppingMallCartSummaryItemOption } from "./IShoppingMallCartSummaryItemOption";

/**
 * Single cart line item in the computed shopping mall cart summary.
 *
 * Each item represents a specific SKU selected by the shopper along with its
 * quantity, pricing snapshot, and human-readable product information. It
 * combines cart item state from guest or customer cart tables with product and
 * SKU metadata for display.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartSummaryItem = {
  /**
   * Opaque identifier of the underlying cart item row from either guest or
   * customer cart items table.
   *
   * The exact source table (guest vs customer) is internal to the
   * implementation and not exposed to clients.
   */
  cartItemId: string;

  /** Identifier of the base product record associated with this cart item. */
  productId: string;

  /** Identifier of the specific SKU (variant) associated with this cart item. */
  skuId: string;

  /**
   * Display name of the product for this cart line, suitable for use in cart
   * and checkout UIs.
   */
  productName: string;

  /**
   * Display name of the SKU or variant, typically including option selections
   * (for example, size or color).
   */
  skuName: string;

  /**
   * URL of the primary product or SKU image used as thumbnail in cart and
   * checkout UIs.
   */
  thumbnailUrl?: (string & tags.Format<"uri">) | null | undefined;

  /**
   * Quantity of this SKU currently in the cart.
   *
   * The value is always at least 1 and represents the number of units that
   * will be considered when computing monetary fields such as lineSubtotal
   * and lineTotal.
   */
  quantity: number & tags.Type<"int32"> & tags.Minimum<1>;

  /**
   * Unit price for a single unit of this SKU at the time of summary
   * computation, expressed in the summary currency.
   *
   * This value is typically taken from the current effective catalog price
   * after applying product- or SKU-level pricing rules but before any line-
   * or cart-level discounts are applied.
   */
  unitPrice: number;

  /**
   * Subtotal for this line before discounts (unitPrice × quantity), expressed
   * in the summary currency.
   *
   * This field is computed by the backend and should be treated as read-only
   * by clients; it represents the pre-discount monetary contribution of this
   * cart line.
   */
  lineSubtotal: number;

  /**
   * Total discount amount applied specifically to this line item, such as
   * per-SKU promotions or coupons, expressed in the summary currency.
   */
  lineDiscountTotal?: number | null | undefined;

  /**
   * Final line total after applying line-specific discounts, expressed in the
   * summary currency.
   *
   * In most cases this is equal to lineSubtotal minus lineDiscountTotal (if
   * any). Additional cart-level discounts or shipping costs may further
   * affect the overall order total but are not reflected here.
   */
  lineTotal: number;

  /**
   * Human-readable option selections associated with this SKU (for example,
   * size=L, color=Blue).
   *
   * Entries correspond to the option dimensions configured on the product and
   * the concrete values chosen for the SKU, making it easy to render variant
   * details in cart and checkout UIs.
   */
  options?: IShoppingMallCartSummaryItemOption[] | undefined;

  /**
   * Indicates whether this SKU is currently considered available for purchase
   * based on product visibility and inventory rules evaluated during summary
   * computation.
   *
   * When false, the cart line may be non-checkoutable (for example, due to
   * the product being disabled, out of stock, or restricted in the shopper's
   * region).
   */
  isAvailable: boolean;

  /**
   * Optional human-readable message describing the availability status of
   * this cart line (for example, "Out of stock", "Limited quantity", or
   * "Product no longer available").
   */
  availabilityMessage?: string | null | undefined;
};
